import argparse
import json
from pathlib import Path
from fast_selection import safe_output

def build(payload,output):
    path=Path(output);safe_output(path.parent);root=Path(__file__).parent
    css=(root/'docs/status.css').read_text();js=(root/'stage3_view.js').read_text()
    data=json.dumps(payload,ensure_ascii=False).replace('<','\\u003c')
    path.write_text('''<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>尾盤 ±3%｜第三階段隔離驗收</title><style>'''+css+'''
    .stage3-panel{margin:18px 0;padding:18px;border:1px solid #273950;border-radius:14px;background:#111b2d;line-height:1.7}.stage3-counts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px}.stage3-counts strong{display:block;font-size:27px}.stage3-counts span,td small,.stage3-evidence{font-size:12px;color:#97abc4}td small{display:block;white-space:normal;max-width:290px}#stage3-mode,.stage3-status{color:#e6bd70}.stage3-controls{display:flex;gap:10px;margin:18px 0}button,select{color:#e3ebfa;background:#172840;border:1px solid #364960;border-radius:7px;padding:8px}th button{background:transparent;border:0;width:100%}th button:hover{background:#213957}th[aria-sort=ascending] .sort-arrow,th[aria-sort=descending] .sort-arrow{color:#66aeff}#stage3-cards{display:none}.desktop-wrap{overflow:auto}@media(max-width:900px){.desktop-wrap{display:none}#stage3-cards{display:grid;gap:12px}.stage3-counts strong{font-size:25px}.stage3-counts span{font-size:11px}}
    </style><main><div class="eyebrow" id="stage3-mode"></div><h1>尾盤 ±3%｜逐檔證據</h1><p class="subtitle">目標 13:35～13:40；實盤正式驗證目標尚未達成。</p><p>交易日 <strong id="stage3-date"></strong></p><section class="stage3-panel stage3-counts"><div><span>研究候選</span><strong id="stage3-research"></strong></div><div><span>正式驗證</span><strong id="stage3-verified"></strong></div><div><span>候選資料不足</span><strong id="stage3-unknown"></strong></div></section><section class="stage3-panel"><p>初篩涵蓋：<span id="stage3-screening"></span></p><p>程式產生：<strong id="stage3-generated"></strong><br>端點寫入：<strong id="stage3-write"></strong><br>本瀏覽器讀取：<strong id="stage3-read">未取得</strong></p><p id="stage3-network">離線檢視；尚未測量真正公開網站讀取。</p><p id="stage3-audit"></p><p>價格尚未獨立驗證時均為參考值；本頁不會下單。</p></section><div class="stage3-controls"><label class="sr-only" for="stage3-sort">成交量排序</label><select id="stage3-sort"><option value="">原始順序</option><option value="closing_auction_volume">最後一盤量</option><option value="intraday_total_volume">全日盤中量</option><option value="closing_volume_ratio_pct">收盤量占比</option></select><button id="stage3-direction">由大到小 ↓</button></div><p id="stage3-empty"></p><div class="desktop-wrap"><table><thead><tr><th>股票與時間</th><th>13:25 前價</th><th>收盤價</th><th>尾盤漲跌</th><th aria-sort="none"><button data-stage3-sort="closing_auction_volume">最後一盤量<span class="sort-arrow">⇅</span></button></th><th aria-sort="none"><button data-stage3-sort="intraday_total_volume">全日盤中量<span class="sort-arrow">⇅</span></button></th><th aria-sort="none"><button data-stage3-sort="closing_volume_ratio_pct">收盤量占比<span class="sort-arrow">⇅</span></button></th><th>驗證狀態</th></tr></thead><tbody id="stage3-rows"></tbody></table></div><div id="stage3-cards"></div><footer>完全隔離測試；正式網站及每日排程未更動。</footer></main><script>window.Stage3Payload='''+data+'''</script><script>'''+js+'''</script><script>window.Stage3Controller=Stage3View.create(document,Stage3Payload);const endpoint=new URL(location.href).searchParams.get('endpoint');if(endpoint){Stage3Controller.poll(endpoint);setInterval(()=>Stage3Controller.poll(endpoint),1500);}</script></html>''')
    return path

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('input',type=Path);p.add_argument('output',type=Path);a=p.parse_args()
    print(build(json.loads(a.input.read_text()),a.output))
